import React, { useState, useEffect, useCallback } from "react";
import "./toast.base.css";

type ToastType = "success" | "error" | "warning" | "info";
type ToastVariant = "outline" | "filled";

interface ToastProps {
  type: ToastType;
  message: string;
  variant?: ToastVariant;
  duration?: number;
  onClose?: () => void;
}

interface ToastEntry {
  id: string;
  type: ToastType;
  message: string;
  variant?: ToastVariant;
  duration?: number;
}

interface ToastContainerProps {
  toasts: ToastEntry[];
  onRemove: (id: string) => void;
}

const Toast: React.FC<ToastProps> = ({
  type,
  message,
  variant = "outline",
  duration = 4000,
  onClose,
}) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isExiting, setIsExiting] = useState(false);

  const handleClose = useCallback(() => {
    setIsExiting(true);
    setTimeout(() => onClose?.(), 300);
  }, [onClose]);

  useEffect(() => {
    const enterTimer = setTimeout(() => setIsVisible(true), 50);
    const exitTimer = setTimeout(() => handleClose(), duration);
    return () => {
      clearTimeout(enterTimer);
      clearTimeout(exitTimer);
    };
  }, [duration, handleClose]);

  const visibilityMod =
    isVisible && !isExiting ? "toast--visible" : "toast--hidden";

  return (
    <div
      className={`toast toast--${type} toast--${variant} ${visibilityMod}`}
      style={{ "--toast-duration": `${duration}ms` } as React.CSSProperties}
    >
      <div
        className={`toast__progress ${
          isExiting ? "toast__progress--exiting" : ""
        }`}
      />
      <div className="toast__message">{message}</div>
      <button
        className="toast__close"
        onClick={handleClose}
        type="button"
        aria-label="Dismiss notification"
      >
        &times;
      </button>
    </div>
  );
};

const ToastContainer: React.FC<ToastContainerProps> = ({
  toasts,
  onRemove,
}) => (
  <div className="toast-container">
    {toasts.map((t) => (
      <Toast
        key={t.id}
        type={t.type}
        message={t.message}
        variant={t.variant}
        duration={t.duration}
        onClose={() => onRemove(t.id)}
      />
    ))}
  </div>
);

export { Toast, ToastContainer };
export type { ToastType, ToastVariant, ToastEntry };
